def shade(c,fill):
    p=c._tc.get_or_add_tcPr(); s=OxmlElement('w:shd'); s.set(qn('w:fill'),fill); p.append(s)
def setcell(c,text,b=False,color=DARK,size=8.5):
    c.text=''; p=c.paragraphs[0]; p.paragraph_format.space_after=Pt(2); r=p.add_run(str(text)); r.bold=b; r.font.size=Pt(size); r.font.color.rgb=RGBColor.from_string(color)
def tbl(doc,heads,rows):
    t=doc.add_table(rows=1,cols=len(heads)); t.alignment=WD_TABLE_ALIGNMENT.CENTER; t.style='Table Grid'
    for c,h in zip(t.rows[0].cells,heads): shade(c,BLUE); setcell(c,h,True,'FFFFFF',8.5)
    for ri,row in enumerate(rows):
        cs=t.add_row().cells
        for c,v in zip(cs,row):
            if ri%2: shade(c,'F7F9FC')
            setcell(c,v)
    doc.add_paragraph(''); return t
