h(doc,'How to use this document'); doc.add_paragraph('This guide is intended for a project maker, developer, or coding agent. It separates confirmed project facts from proposed implementation decisions. The supplied capstone requirements and screen references define what the admin must do; the repository defines how it should be built today.')
tbl(doc,['Evidence type','How it is used'],[('Project repository','Authoritative for current framework, folder conventions, dependencies, and existing code.'),('Supplied requirements PDFs','Authoritative for business scope, module responsibilities, role expectations, and workflow intent.'),('Supplied admin screen PDF','Visual reference for navigation, labels, tables, cards, status names, and information density.'),('This specification','Implementation-ready interpretation. Proposed items should be confirmed before production.')])
h(doc,'Executive build decision'); doc.add_paragraph('Build the admin as a protected Next.js App Router application using TypeScript, HeroUI, Tailwind CSS, Lucide icons, Prisma 7, and PostgreSQL. Keep server-side reads and mutations close to the feature that owns them. The current repository is a starter template, so business tables, authentication, authorization, audit trail, reporting, and backup flows remain to be implemented.')
h(doc,'Current repository baseline'); tbl(doc,['Area','Current choice','Guidance'],[('Framework','Next.js 16 App Router','Use app/ routes and server components by default.'),('Language','TypeScript 5.6','Use strict types for domain records and payloads.'),('UI','HeroUI 3.2.5 + Tailwind 4','Do not introduce a second design system.'),('Database','PostgreSQL + Prisma 7.10','Replace starter user/contact schema with domain schema.'),('Icons','lucide-react','Use consistently in nav, actions, status, and empty states.'),('Existing nav','components/ui/sidebar.tsx','Expand current items into grouped admin navigation.')])
h(doc,'1 Product vision and admin scope'); doc.add_paragraph('The web admin is the operational control center for product catalog, stock, customers, orders, payments, delivery, returns, feedback, marketing, reports, auditability, and data recovery. It replaces notebooks, receipt books, spreadsheets, social-message coordination, and manual stock checks with one operational source of truth.')
h(doc,'Primary users',2); tbl(doc,['Role','Purpose','Access posture'],[('Owner','Manage the business, users, reports, system controls, backups, and all records.','Full access including restore.'),('Staff','Process catalog, inventory, customers, orders, payments, delivery, returns, feedback, marketing, and reports.','Operational access; limited audit/system controls.'),('Customer and delivery roles','Outside the present web-admin focus; represented as linked records/events.','Do not expose their separate surfaces here yet.')])
h(doc,'Navigation information architecture',2); tbl(doc,['Group','Routes'],[('Overview','/dashboard'),('Operations','/orders, /inventory, /delivery-personnel, /returns-refunds'),('Customers','/customers, /feedback, /payments'),('Catalog and Marketing','/products, /heritage-showcase, /promotions, /notifications'),('System','/reports, /audit-logs, /backup-restore, /users, /settings')])
h(doc,'2 Visual and interaction direction'); doc.add_paragraph('The supplied screen references show a desktop-first shell with persistent left navigation, top utility bar, global search, compact data tables, status badges, export actions, date filters, and dashboard cards. Preserve this information architecture while making it responsive enough for tablet use.')
if IMG.exists():
    p=doc.add_paragraph(); p.alignment=1; p.add_run().add_picture(str(IMG),width=Inches(6.5)); p=doc.add_paragraph('Figure 1. Supplied administration screen reference. Use it as a visual guide, not a pixel-perfect constraint.'); p.alignment=1; p.runs[0].italic=True; p.runs[0].font.size=Pt(8.5)
h(doc,'Shell rules',2)
for x in ['Desktop: persistent sidebar around 240 px; content scrolls independently.','Top bar: product name, global search, notifications, current role, account menu, sign out.','Tables: search/filter row, pagination, loading/empty/error states, confirmation for destructive actions.','Statuses use text plus color; never rely on color alone.','Forms validate on the server, show field-level errors, preserve safe values, and confirm successful mutations.']: b(doc,x)
h(doc,'3 Technical architecture'); doc.add_paragraph('Use a feature-oriented App Router structure. Server components fetch through typed server functions. Route handlers serve client-triggered mutations, exports, webhooks, and files. Authorization lives in a reusable server-only helper; a hidden button is never the security boundary.')
code(doc,'app/(admin)/dashboard/page.tsx\napp/(admin)/orders/page.tsx\napp/(admin)/inventory/page.tsx\napp/(admin)/products/page.tsx\napp/(admin)/customers/page.tsx\napp/(admin)/reports/page.tsx\napp/api/admin/[resource]/route.ts\ncomponents/admin/\nlib/auth.ts  lib/permissions.ts  lib/audit.ts  lib/db.ts  lib/validation.ts\nprisma/schema.prisma  prisma/seed.ts  types/admin.ts')
h(doc,'Request lifecycle',2); tbl(doc,['Step','Implementation rule'],[('Request','Browser requests page or submits form.'),('Authentication','Read server session; reject missing/expired sessions.'),('Authorization','Check role and exact permission for action.'),('Validation','Parse input with shared schema; reject unexpected fields.'),('Transaction','Use Prisma transaction for related updates.'),('Audit','Write immutable record for meaningful mutation/export.'),('Response','Return typed result; revalidate affected route.')])
h(doc,'4 Authentication and authorization'); doc.add_paragraph('The requirements call for secure Owner and Staff login plus one-time verification and password recovery. The supplied screens show username/email login, six-digit verification, forgot password, reset password, and success states. Implement these as a separate auth surface before the protected shell.')
for x in ['Login accepts username or email plus password and records success/failure security events.','Use server-managed, httpOnly, secure, sameSite session cookies; never store admin passwords or session tokens in localStorage.','Store only a strong password hash. Enforce minimum length and rate-limit login, verification, and reset attempts.','Verification codes are single-use, expire after five minutes, and are stored hashed if persisted.','Sign out invalidates the session; sensitive actions may require fresh authentication.']: b(doc,x)
h(doc,'Permission matrix',2); tbl(doc,['Module/action','Owner','Staff'],[('Dashboard and operational reads','Allow','Allow'),('Products, inventory, customers, orders, delivery, returns, feedback, payments','Allow','Allow'),('Marketing and notifications','Allow','Policy-based'),('Reports and exports','Allow','Allow'),('Audit logs','All records','Own activity or limited subset'),('Users and roles','Allow','Deny'),('Backup create/download','Allow','Deny or view-only'),('Restore data','Allow with confirmation','Deny')])
h(doc,'5 Data model blueprint'); doc.add_paragraph('The existing Prisma schema contains only generic user and contacts tables. This is the proposed minimum domain model; confirm final names before migration.')
tbl(doc,['Entity','Important fields','Relationships and notes'],[('admin_user','id, email, username, password_hash, role, status, last_login_at','Owner/Staff; separate from customers.'),('customer','id, name, email, phone, status','Owns addresses, orders, feedback.'),('product','id, sku, name, category_id, price, image_url, reorder_level, status, featured','Catalog and Heritage Showcase.'),('inventory_movement','id, product_id, type, quantity, reason, reference_id, created_by','Stock in/out/adjustment; never erase history.'),('order and order_item','id, customer_id, status, total_amount, fulfillment_method','Constrained status transitions.'),('payment','id, order_id, method, amount, reference, receipt_url, status, verified_by','Verification updates order in transaction.'),('return_request','id, order_id, reason, status, decision_note, decided_by','Approved refund creates reversal.'),('feedback','id, product_id, customer_id, rating, comment, moderation_status','Flagged content hidden from storefront.'),('audit_log','id, actor_id, role, module, action, entity_id, ip_address, metadata, created_at','Append-only.'),('backup_record','id, type, storage_key, size_bytes, status, created_at','Owner restore only.')])
h(doc,'Order and inventory invariants',2)
