for x in ['Validate every route on the server; client validation is usability only.','Use parameterized Prisma queries; never concatenate user-controlled SQL.','Protect CSRF-sensitive mutations according to the chosen auth/session model.','Redact receipts, passwords, reset tokens, and sensitive metadata from logs.','Use least privilege for database credentials and separate backup storage.','Make large exports asynchronous and enforce date/row limits.','Add error boundaries and loading/empty states; never expose stack traces.']: b(doc,x)
h(doc,'9 Delivery plan'); tbl(doc,['Phase','Deliverables','Exit condition'],[('1 Foundation','Auth/session, shell, permissions, DB client, migrations, seed.','Owner/Staff sign in and reach permitted routes.'),('2 Core operations','Products, inventory, customers, orders, payments.','Test order completes with safe stock/payment changes.'),('3 Extended operations','Delivery, returns, feedback, marketing/notifications.','Edge cases are traceable.'),('4 Intelligence and control','Dashboard, reports, audit, backup/restore.','Owner can monitor, export, audit, recover.'),('5 Hardening','Accessibility, responsive QA, rate limits, tests, deployment.','No critical security/data defects.')])
